function zoomJobMap(delta){jobMap.zoom=Math.max(4,Math.min(17,jobMap.zoom+delta));renderJobMap()}
document.getElementById('mapZoomIn').addEventListener('click',()=>zoomJobMap(1));document.getElementById('mapZoomOut').addEventListener('click',()=>zoomJobMap(-1));document.getElementById('mapCanvas').addEventListener('wheel',event=>{if(!document.getElementById('mapCanvas').classList.contains('show'))return;event.preventDefault();zoomJobMap(event.deltaY<0?1:-1)},{passive:false});
document.getElementById('mapCanvas').addEventListener('pointerdown',event=>{if(event.target.closest('button,a'))return;jobMap.dragging=true;jobMap.start={x:event.clientX,y:event.clientY,center:{...jobMap.center}};document.getElementById('mapCanvas').setPointerCapture(event.pointerId)});document.getElementById('mapCanvas').addEventListener('pointermove',event=>{if(!jobMap.dragging)return;jobMap.delta={x:event.clientX-jobMap.start.x,y:event.clientY-jobMap.start.y};document.getElementById('mapTiles').style.transform=`translate(${jobMap.delta.x}px,${jobMap.delta.y}px)`;document.getElementById('mapPins').style.transform=`translate(${jobMap.delta.x}px,${jobMap.delta.y}px)`});function finishMapDrag(){if(!jobMap.dragging)return;jobMap.dragging=false;const delta=jobMap.delta||{x:0,y:0},center=mapWorldPoint(jobMap.start.center.lat,jobMap.start.center.lng,jobMap.zoom),scale=256*2**jobMap.zoom,x=center.x-delta.x,y=center.y-delta.y,lng=x/scale*360-180,n=Math.PI-2*Math.PI*y/scale,lat=180/Math.PI*Math.atan(Math.sinh(n));jobMap.center={lat:Math.max(-85,Math.min(85,lat)),lng};jobMap.delta=null;document.getElementById('mapTiles').style.transform='';document.getElementById('mapPins').style.transform='';renderJobMap()}document.getElementById('mapCanvas').addEventListener('pointerup',finishMapDrag);document.getElementById('mapCanvas').addEventListener('pointercancel',finishMapDrag);
document.getElementById('listView').onclick=()=>{currentPage=1;document.getElementById('listView').classList.add('active');document.getElementById('mapView').classList.remove('active');render()};
document.getElementById('mapView').onclick=()=>{currentPage=1;document.getElementById('mapView').classList.add('active');document.getElementById('listView').classList.remove('active');render()};
document.querySelector('a[href="#ofertas"]').addEventListener('click',()=>{currentPage=1;showSaved=false;showAlerts=false;render()});
document.getElementById('alertLink').addEventListener('click',event=>{event.preventDefault();if(!currentUser){openAuth();return}showAlerts=true;showSaved=false;render();document.getElementById('alertsPanel').scrollIntoView({behavior:'smooth',block:'start'})});
document.getElementById('savedLink').addEventListener('click',event=>{event.preventDefault();if(!currentUser){openAuth();return}currentPage=1;showSaved=true;showAlerts=false;render();document.getElementById('ofertas').scrollIntoView({behavior:'smooth'})});
document.getElementById('alertForm').addEventListener('submit',saveAlert);
document.getElementById('alertsList').addEventListener('click',event=>{const button=event.target.closest('button[data-action]');if(!button)return;const alert=alerts.find(item=>item.id===button.dataset.id);if(!alert)return;if(button.dataset.action==='delete'){alerts=alerts.filter(item=>item.id!==alert.id);persistAccountData();renderAlerts();return}document.getElementById('keyword').value=alert.keyword;document.getElementById('area').value=alert.area;document.getElementById('radius').value=alert.radius;document.getElementById('salary').value=alert.salary;document.getElementById('salaryValue').textContent=Number(alert.salary).toLocaleString('es-ES')+' €';document.querySelectorAll('.kind').forEach(item=>item.checked=item.value===alert.kind);document.querySelectorAll('.mode').forEach(item=>item.checked=item.value===alert.mode);currentPage=1;showAlerts=false;showSaved=false;render();document.getElementById('ofertas').scrollIntoView({behavior:'smooth'})});
document.getElementById('alertsList').addEventListener('change',event=>{const toggle=event.target.closest('input[data-email-alert]');if(!toggle||!currentUser)return;const alert=alerts.find(item=>item.id===toggle.dataset.emailAlert);if(!alert)return;alert.emailEnabled=toggle.checked;alert.notifiedJobIds=toggle.checked?matchingAlertJobs(alert).map(job=>job.url):[];persistAccountData();renderAlerts()});
document.getElementById('pagination').addEventListener('click',event=>{const button=event.target.closest('button[data-page]');if(!button||button.disabled)return;currentPage=Number(button.dataset.page);render();document.getElementById('resultsTitle').scrollIntoView({behavior:'smooth',block:'center'})});
document.getElementById('pageSize').addEventListener('change',()=>{currentPage=1;render()});
document.getElementById('search').onclick=()=>{currentPage=1;showAlerts=false;showSaved=false;render()};
document.getElementById('keyword').addEventListener('keydown',event=>{if(event.key==='Enter'){currentPage=1;showAlerts=false;showSaved=false;render()}});
document.getElementById('salary').oninput=event=>{document.getElementById('salaryValue').textContent=Number(event.target.value).toLocaleString('es-ES')+' €';currentPage=1;showAlerts=false;render()};
document.getElementById('alertSalary').oninput=event=>{document.getElementById('alertSalaryValue').textContent=Number(event.target.value).toLocaleString('es-ES')+' €'};
document.querySelectorAll('.kind,.mode,#area,#radius,#sort').forEach(item=>item.addEventListener('change',()=>{currentPage=1;showAlerts=false;render()}));
function updateProfileUI(){const label=document.getElementById('profileLabel');label.textContent=currentUser?currentUser.name.split(' ')[0]:'Mi perfil';document.getElementById('menuProfileName').textContent=currentUser?.name||'';document.getElementById('menuProfileEmail').textContent=currentUser?.email||'';document.getElementById('alertLink').hidden=!currentUser;document.getElementById('savedLink').hidden=!currentUser;const emailToggle=document.getElementById('alertEmailEnabled');emailToggle.disabled=!currentUser;emailToggle.checked=Boolean(currentUser);document.getElementById('alertEmailHint').textContent=currentUser?`Se enviarán a ${currentUser.email}. ${emailNotificationsReady?'':'El servidor aún no tiene el correo configurado.'}`:'Inicia sesión para recibirlas en el email de tu cuenta.'}
function toggleProfileMenu(force){const menu=document.getElementById('profileMenu');const open=force??menu.hidden;menu.hidden=!open;document.getElementById('profile').setAttribute('aria-expanded',String(open))}
function showProfileDetails(){if(!currentUser)return;toggleProfileMenu(false);document.getElementById('profileNameValue').textContent=currentUser.name;document.getElementById('profileEmailValue').textContent=currentUser.email;document.getElementById('profileSavedValue').textContent=String(jobs.filter(job=>saved.includes(job.title)).length);document.getElementById('profileAlertsValue').textContent=String(alerts.length);document.getElementById('profileBackdrop').hidden=false}
document.getElementById('profile').onclick=()=>currentUser?toggleProfileMenu():openAuth();
document.getElementById('profileDetails').onclick=showProfileDetails;
document.getElementById('profileLogout').onclick=logout;
document.getElementById('profileClose').onclick=()=>document.getElementById('profileBackdrop').hidden=true;
document.getElementById('profileDone').onclick=()=>document.getElementById('profileBackdrop').hidden=true;
document.getElementById('profileBackdrop').addEventListener('click',event=>{if(event.target.id==='profileBackdrop')event.currentTarget.hidden=true});
document.addEventListener('click',event=>{if(!event.target.closest('.profile-menu-wrap'))toggleProfileMenu(false)});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){toggleProfileMenu(false);document.getElementById('profileBackdrop').hidden=true}});
document.getElementById('notice').style.display='block';
render();

async function api(path,options={}){const response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})},credentials:'same-origin'});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'No se pudo completar la operación.');return payload}
function persistAccountData(){if(!currentUser)return Promise.resolve();return api('/api/account/data',{method:'PUT',body:JSON.stringify({savedJobs:saved,alerts})}).catch(error=>console.error(error))}
function openAuth(){authMode='login';updateAuthMode();document.getElementById('authBackdrop').hidden=false;document.getElementById('authEmail').focus()}
function closeAuth(){document.getElementById('authBackdrop').hidden=true;document.getElementById('authError').textContent=''}
function updateAuthMode(){const signup=authMode==='register';document.getElementById('authTitle').textContent=signup?'Crear cuenta':'Inicia sesión';document.getElementById('authDescription').textContent=signup?'Regístrate para guardar tus alertas y ofertas en tu cuenta.':'Accede a tus alertas y ofertas guardadas desde cualquier sesión.';document.getElementById('authNameWrap').hidden=!signup;document.getElementById('authName').required=signup;document.getElementById('authPassword').autocomplete=signup?'new-password':'current-password';document.getElementById('authSubmit').textContent=signup?'Crear cuenta':'Iniciar sesión';document.getElementById('authSwitchText').textContent=signup?'¿Ya tienes una cuenta?':'¿Aún no tienes cuenta?';document.getElementById('authSwitch').textContent=signup?'Iniciar sesión':'Crear cuenta'}
async function logout(){try{await api('/api/logout',{method:'POST',body:'{}'})}catch(error){console.error(error)}currentUser=null;saved=[];alerts=[];showSaved=false;showAlerts=false;toggleProfileMenu(false);updateProfileUI();render()}
document.getElementById('authClose').onclick=closeAuth;
document.getElementById('authBackdrop').addEventListener('click',event=>{if(event.target.id==='authBackdrop')closeAuth()});
document.getElementById('authSwitch').onclick=()=>{authMode=authMode==='login'?'register':'login';updateAuthMode()};
document.getElementById('authForm').addEventListener('submit',async event=>{event.preventDefault();const error=document.getElementById('authError');error.textContent='';const route=authMode==='register'?'/api/register':'/api/login';const anonymous={savedJobs:saved.slice(),alerts:alerts.slice()};try{const result=await api(route,{method:'POST',body:JSON.stringify({name:document.getElementById('authName').value,email:document.getElementById('authEmail').value,password:document.getElementById('authPassword').value})});currentUser=result.user;if(authMode==='register'){saved=anonymous.savedJobs;alerts=anonymous.alerts;await persistAccountData()}else{saved=result.user.savedJobs||[];alerts=result.user.alerts||[]}emailNotificationsReady=Boolean(result.emailNotificationsReady);try{const sync=await api('/api/jobs/sync',{method:'POST',body:JSON.stringify({jobs})});emailNotificationsReady=Boolean(sync.emailNotificationsReady)}catch(syncError){console.warn('No se pudo sincronizar las alertas por correo:',syncError.message)}updateProfileUI();closeAuth();render()}catch(err){error.textContent=err.message}});
document.getElementById('homeLink').addEventListener('click',event=>{event.preventDefault();showAlerts=false;showSaved=false;render();window.scrollTo({top:0,behavior:'smooth'})});
api('/api/session').then(async result=>{emailNotificationsReady=Boolean(result.emailNotificationsReady);if(result.user){currentUser=result.user;saved=result.user.savedJobs||[];alerts=result.user.alerts||[];try{const sync=await api('/api/jobs/sync',{method:'POST',body:JSON.stringify({jobs})});emailNotificationsReady=Boolean(sync.emailNotificationsReady)}catch(error){console.warn('No se pudo sincronizar las alertas por correo:',error.message)}}updateProfileUI();renderAlerts();render()}).catch(()=>{updateProfileUI();render()});






